pub struct MessageMediaFile {
    /// Always `media`.
    pub object: String,
    #[serde(rename = "messageId")]
    pub message_id: String,
    /// The file. No API key needed.
    pub url: String,
    #[serde(rename = "mimeType")]
    pub mime_type: Option<String>,
    pub filename: Option<String>,
    /// Bytes, when known.
    pub size: Option<i64>,
}

