string_enum! {
    /// - `pending`: Created or resent.
    /// - `in_progress`: The invitee started linking and the account exists.
    /// - `completed`: The account reached `ready`.
    /// - `failed`: Linking stopped (`failureReason`); the link keeps working and a retry reuses the account.
    /// - `cancelled`: Cancelled by you.
    /// - `expired`: Pending or failed past `expiresAt`. Computed on read, never stored.
    pub enum InvitationStatus {
        /// `pending`
        Pending = "pending",
        /// `in_progress`
        InProgress = "in_progress",
        /// `completed`
        Completed = "completed",
        /// `failed`
        Failed = "failed",
        /// `cancelled`
        Cancelled = "cancelled",
        /// `expired`
        Expired = "expired",
        @unknown Unknown,
    }
}

string_enum! {
    /// - `qr_code`: Scan a live QR code.
    /// - `pairing_code`: Type an 8-character pairing code on the phone.
    pub enum InvitationMethod {
        /// `qr_code`
        QrCode = "qr_code",
        /// `pairing_code`
        PairingCode = "pairing_code",
        @unknown Unknown,
    }
}

